/** Captured material is explicitly synthetic; exercise the actual evidence-ledger validators. */
function nasaCapturedEvidence(AIcontrol\Investigation $engine,PDO $db,int $run): array
{
    $claim=$engine->appendNode($run,null,'dream_claim','complete','Reject expired owner sessions','The system rejects expired sessions before writing private records.');
    $data=['claim'=>'The system rejects expired sessions before writing private records.','uncertainty'=>'Synthetic fixture only.','test'=>'Run an expired-session integration check.'];
    $db->prepare('UPDATE research_nodes SET data_json=? WHERE id=?')->execute([json_encode($data,JSON_THROW_ON_ERROR),$claim]);
    $search=$engine->appendNode($run,$claim,'search','complete','Synthetic captured result','Captured fixture material, not a live provider search.');
    $exact='Synthetic fixture report: an expired session returned HTTP 401 and no private record was written.';
    $meta=['provider_snippets'=>[['text'=>$exact,'scope'=>'provider_snippet','locator'=>'fixture:1']]];
    $db->prepare('INSERT INTO research_sources(run_id,node_id,url,title,extract,domain,retrieved_at,meta_json)VALUES(?,?,?,?,?,?,?,?)')->execute([$run,$search,'https://example.test/session-result','Synthetic session test report',$exact,'example.test',time(),json_encode($meta,JSON_THROW_ON_ERROR)]);$source=(int)$db->lastInsertId();
    $passage=$engine->addPassage($source,$run,$exact,'fixture:1');$edge=$engine->addEdge($run,$claim,$passage,$source,'supports','Captured synthetic result relates to the expiry check.','low');
    $engine->recordClaimVersion($claim,$run,'supported','Synthetic grouped model check, not owner approval.','low','verifier');$version=(int)$db->query('SELECT MAX(id) FROM research_claim_versions')->fetchColumn();
    $idea=$engine->appendNode($run,null,'model_idea','complete','Try a recovery boundary','Provisional model idea: explore expired-session recovery.');
    return compact('claim','search','source','passage','edge','version','idea');
}

